#!/bin/zsh
cd /Users/todd/StudioProjects/macroscope
S=plan/logs/_codex_finish.txt; : > $S
CX=(codex --search exec -C . -s workspace-write --skip-git-repo-check -c model_reasoning_effort=high)

$CX -o plan/logs/A-codex-synth.last.md "Read plan/BRIEF.md, then EVERY file in plan/research/ (15 reports). Write the single master plan to plan/PLAN.md. It must be a decision document a solo developer can build from, not a summary. Where reports disagree (stack, UX model, cost, MVP scope), pick one, give one sentence of why, and note the rejected option in a 'Key decisions' table. Keep concrete detail (schemas, manifest example, process diagram, MSP-to-UI mapping, API-key flow, permission sequence, ASCII wireframes for onboarding, menu bar, Discoveries, Opportunity detail, Builder with Muse transcript and terminal toggle, run/trust/repair, Privacy center). Sections: 0 summary + key decisions; 1 product (persona, v1 wedge, first 10 workflows, MVP in/out, metrics); 2 UX (principles, IA, wireframes, discover->build->test->trust->repair flow); 3 architecture (stack, process model, IPC, storage, repo tree); 4 Meta models and Muse integration (routing table, provider abstraction, muse serve hosting, MSP mapping, API-key auth section stating what is VERIFIED per plan/research/04-muse-msp.md section 0 versus unverified); 5 capture (macOS, Windows, observer interface, permissions, budgets); 6 pattern engine; 7 micro-apps (SDK/DSL vs full code, manifest, runtimes, sandboxing, tests, repair); 8 privacy and security (threat model, prompt-injection defences, MUST-for-MVP); 9 cost and performance budgets, evals, release gates; 10 roadmap M0..Mn macOS first then Windows, with the first two weeks in detail including an end-to-end spike (capture + muse serve + API key); 11 ranked risks with kill criteria; 12 open questions for the owner (deduplicated, each with a recommended answer). Mark unverified facts. Aim for 9,000-14,000 words." >> plan/logs/_codex_finish.log 2>&1
echo "synth exit=$? $(date +%T) plan=$(wc -c < plan/PLAN.md 2>/dev/null)" >> $S

$CX -o plan/logs/B-codex-review.last.md "Read plan/BRIEF.md and plan/PLAN.md; consult plan/research and plan/probes to check claims. Act as a hard-nosed technical reviewer and red team. Write plan/reviews/codex-review.md: (1) the 10 most important problems ranked, each with evidence and a concrete fix (wrong or unverified API claims for macOS/Windows, Meta/Muse, API-key auth, muse serve/MSP; infeasible scope for a solo dev; missing pieces; security holes; cost errors; internal contradictions); (2) anything that blocks the first two-week spike; (3) what the plan gets right and must keep. Also review the UX: is v1 sharp, does a first user get value in 30 minutes, are trust and permission moments handled, is the Builder understandable to a non-developer. Use web search where in doubt. Do not edit PLAN.md." >> plan/logs/_codex_finish.log 2>&1
echo "review exit=$? $(date +%T) bytes=$(wc -c < plan/reviews/codex-review.md 2>/dev/null)" >> $S

$CX -o plan/logs/C-codex-revise.last.md "Read plan/BRIEF.md, plan/PLAN.md and plan/reviews/codex-review.md. Revise plan/PLAN.md in place to address each review point you agree with, verifying against plan/research and plan/probes when you disagree with a reviewer. Keep the structure and concrete detail. Then write plan/reviews/CHANGES.md: a table of each review point -> accepted or rejected -> what changed or why rejected." >> plan/logs/_codex_finish.log 2>&1
echo "revise exit=$? $(date +%T) plan=$(wc -c < plan/PLAN.md)" >> $S
echo DONE >> $S
